def _cleanup_candidates(self, directory: str) -> None:
    """Remove every residual .ledger-* snapshot next to the main file.

    After recovery these are by definition unusable leftovers: older
    generations, an identical post-promotion residue, or a partially
    written (invalid) file. The promoted/main state is never touched.
    """
    main_name = os.path.basename(self.path)
    for name in list(os.listdir(directory)):
        if not name.startswith(SNAPSHOT_PREFIX) or name == main_name:
            continue
        full = os.path.join(directory, name)
        try:
            if os.path.isfile(full) or os.path.islink(full):
                os.unlink(full)
        except OSError:
            pass
    self._fsync_dir(directory)

@staticmethod
def _read_candidate(path: str) -> dict:
    """Read and JSON-decode one snapshot file.

    Any I/O or JSON failure becomes a StateRecoveryError carrying the
    offending path, never a silent fall-back.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except OSError as exc:
        raise StateRecoveryError(path, f"cannot read file: {exc}") from exc
    except (ValueError, UnicodeDecodeError) as exc:
        raise StateRecoveryError(path, f"invalid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise StateRecoveryError(path, "snapshot root must be a JSON object")
    return data

def _parse_snapshot(
    self, path: str, data: dict
) -> tuple[
    list[Block],
    dict[str, Transaction],
    int,
    dict[str, list[Block]],
    int | None,
    dict[tuple[str, str], dict],
    dict[str, dict],
    dict[str, int],
    list[dict],
    list[tuple[str, str, dict]],
    dict,
    bool,
    tuple[dict | None, list[dict], bool],
    str | None,
    dict[tuple[str, str], dict],
    list[tuple[str, str, dict]],
    dict[str, list[dict]],
    bool,
    dict | None,
    dict[str, dict],
]:
    """Strictly validate one decoded snapshot.

    Checks the persisted generation, consecutive heights, prev_hash
    linkage, recomputed block hashes, recomputed Merkle roots, every
    transaction's tx_id and Ed25519 signature, the pending-only-at-tip
    rule, and de-duplication between mempool and chain. Returns the parsed
    chain, mempool, generation, candidate forks and the recorded initial
    balance. Raises StateRecoveryError on the first defect, with ``path``
    identifying the candidate.
    """
    def fail(reason: str) -> None:
        raise StateRecoveryError(path, reason)

    chain_raw = data.get("chain")
    if not isinstance(chain_raw, list) or not chain_raw:
        fail("snapshot must contain a non-empty chain")

    state = data.get("state")
    # A pre-state-section snapshot is accepted: the chain itself is fully
    # self-verifying below. A present non-object section is corruption.
    if state is None:
        state = {}
    if not isinstance(state, dict):
        fail("invalid 'state' section: must be a JSON object")
    generation = state.get("generation", 0)
    # bool is an int subclass; reject it explicitly along with negatives.
    if isinstance(generation, bool) or not isinstance(generation, int) or generation < 0:
        fail("state.generation must be a non-negative integer")
    # Schema version gating the one-time pre-checkpoint-auth migration: a
    # snapshot written by current code always carries state.version >= 9,
    # so a present signer section is mandatory there; only a snapshot whose
    # version explicitly predates 9 may lack the signer sections at all.
    state_version = state.get("version")
    if state_version is not None and (
        isinstance(state_version, bool)
        or not isinstance(state_version, int)
        or state_version < 1
    ):
        fail("state.version must be a positive integer")
    initial_balance = state.get("initial_balance")
    if initial_balance is not None and (
        isinstance(initial_balance, bool)
        or not isinstance(initial_balance, int)
        or initial_balance <= 0
    ):
        fail("state.initial_balance must be a positive integer")
    recorded_state_root = state.get("state_root")
    if recorded_state_root is not None and not crypto.is_hex64(
        recorded_state_root
    ):
        fail("state.state_root must be 64 lowercase hex characters")

    chain: list[Block] = []
    seen_tx_ids: set[str] = set()
    for i, block_raw in enumerate(chain_raw):
        if not isinstance(block_raw, dict):
            fail(f"block at position {i} is not a JSON object")
        try:
            block = Block.from_dict(block_raw)
        except (KeyError, TypeError, ValueError) as exc:
            fail(f"block {i} is malformed: {exc}")
        if block.height != i:
            fail(
                f"block at position {i} has non-consecutive height "
                f"{block.height}"
            )
        expected_prev = GENESIS_PREV_HASH if i == 0 else chain[i - 1].block_hash
        if block.prev_hash != expected_prev:
            fail(f"block {block.height} has a mismatched prev_hash")
        if block.status not in (STATUS_PENDING, STATUS_CONFIRMED):
            fail(f"block {block.height} has unknown status {block.status!r}")
        if i == 0 and (
            block.status != STATUS_CONFIRMED or block.transactions
        ):
            fail("genesis block must be confirmed and carry no transactions")
        # Pending blocks may only sit at the chain tip.
        if i < len(chain_raw) - 1 and block.status == STATUS_PENDING:
            fail(f"pending block {block.height} is not the chain tip")

        # Validate every transaction: stored tx_id, recomputed tx_id and
        # the Ed25519 signature.
        tx_ids: list[str] = []
        txs_raw = block_raw.get("transactions")
        if not isinstance(txs_raw, list):
            fail(f"block {block.height} transactions must be a list")
        for j, tx in enumerate(block.transactions):
            self._validate_transaction(path, tx)
            stored_tx_id = txs_raw[j].get("tx_id") if isinstance(txs_raw[j], dict) else None
            if stored_tx_id != tx.tx_id:
                fail(
                    f"transaction in block {block.height} has a mismatched "
                    f"tx_id (stored {stored_tx_id!r}, recomputed {tx.tx_id})"
                )
            if tx.tx_id in seen_tx_ids:
                fail(
                    f"duplicate transaction {tx.tx_id} in block "
                    f"{block.height}"
                )
            seen_tx_ids.add(tx.tx_id)
            tx_ids.append(tx.tx_id)
        # Blocks store transactions in ascending tx_id order.
        if tx_ids != sorted(tx_ids):
            fail(f"block {block.height} transactions are not tx_id sorted")

        recomputed_merkle = crypto.merkle_root(tx_ids)
        if recomputed_merkle != block.merkle_root:
            fail(f"block {block.height} Merkle root mismatch")
        recomputed_hash = compute_block_hash(
            block.height, block.prev_hash, block.merkle_root
        )
        if recomputed_hash != block.block_hash:
            fail(f"block {block.height} block_hash mismatch")

def _fork_summary(blocks: list) -> dict:
    """Public fork descriptor S: tip_hash, height, length, status."""
    tip = blocks[-1]
    return {
        "tip_hash": tip.block_hash,
        "height": tip.height,
        # The length counts every block including the genesis block.
        "length": len(blocks),
        "status": tip.status,
    }

def _winning_fork(self) -> tuple[str, list]:
    """Pick the winner among the canonical chain and every candidate.

    Longest chain wins; equal lengths are broken by the smallest tip hash
    (lexicographic hex order). Returns (tip_hash, block list).
    """
    contenders: list[tuple[str, list]] = [
        (self.store.tip_hash(), self.store.chain)
    ]
    contenders.extend(self.store.forks.items())
    contenders.sort(key=lambda item: (-len(item[1]), item[0]))
    return contenders[0]

def submit_fork_candidate(self, payload: object) -> tuple[int, dict]:
    """POST /v1/forks/candidates — validate and store a candidate fork.

    Returns 201 with the fork descriptor S. Malformed or invalid forks
    return 400; a fork already known (identical to the canonical tip or an
    existing candidate tip) returns 409.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    blocks_raw = payload.get("blocks")
    if not isinstance(blocks_raw, list):
        return 400, {"error": "missing field: blocks (must be a list)"}
    try:
        fork = self.store.validate_fork_blocks(blocks_raw)
    except ValueError as exc:
        return 400, {"error": str(exc)}
    summary = self._fork_summary(fork)
    # An exported fork (the five-field {tip_hash, height, length, status,
    # blocks} document) may be resubmitted verbatim; every supplied summary
    # field is re-verified against the recomputed descriptor.
    for field in ("tip_hash", "height", "length", "status"):
        if field in payload and payload[field] != summary[field]:
            return 400, {"error": f"summary field {field!r} does not match the blocks"}
    tip_hash = fork[-1].block_hash
    with self.store.lock:
        self._prune_expired_syncs()
        # A tip hash equal to any canonical block hash means the candidate
        # is exactly the canonical chain or a prefix of it (the block hash
        # binds height, parent and Merkle root), so it carries nothing new.
        if any(tip_hash == block.block_hash for block in self.store.chain):
            return 409, {"error": "fork is identical to the canonical chain"}
        if tip_hash in self.store.forks:
            return 409, {"error": "candidate fork already exists", "tip_hash": tip_hash}
        self.store.forks[tip_hash] = fork
        try:
            self.store.save()
        except BaseException:
            self.store.forks.pop(tip_hash, None)

def list_audit_events(self, params: dict) -> tuple[int, dict]:
    """GET /v1/audit/events — paginated append-only audit log.

    Filters ``source`` and ``kind`` are AND-combined; ``limit`` defaults
    to 50 and must be 1-200, ``cursor`` defaults to 0. Numeric values
    must be plain decimals without leading zeros. Events are ordered by
    their ascending ``event_id``; ``cursor == total`` returns an empty
    page, ``cursor > total`` returns 400.
    """
    source = params.get("source")
    if source is not None and (not isinstance(source, str) or not source):
        return 400, {"error": "source must be a non-empty string"}
    kind = params.get("kind")
    if kind is not None and (not isinstance(kind, str) or not kind):
        return 400, {"error": "kind must be a non-empty string"}
    limit = self.AUDIT_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.AUDIT_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 200"}
        limit = parsed
    cursor = 0
    if params.get("cursor") is not None:
        parsed = _parse_decimal(params["cursor"])
        if parsed is None:
            return 400, {"error": "cursor must be a non-negative decimal"}
        cursor = parsed

    with self.store.lock:
        # Sweep expired syncs first so their expiry events are visible on
        # the same page that observes the removal.
        self._prune_expired_syncs()
        items = [
            dict(event)
            for event in self.store.audit_events
            if (source is None or event.get("source") == source)
            and (kind is None or event.get("kind") == kind)
        ]
    # Events are stored in ascending event_id order; filtering preserves it.
    total = len(items)
    if cursor > total:
        return 400, {"error": "cursor is beyond the result set"}
    page = items[cursor : cursor + limit]
    next_cursor = cursor + limit if cursor + limit < total else None
    return 200, {"items": page, "total": total, "next_cursor": next_cursor}

def export_audit_events(self, params: dict) -> tuple[int, dict]:
    """GET /v1/audit/export — hash-anchored export page for offline checks.

    Pagination is identical to ``GET /v1/audit/events`` for the *whole*
    log (no source/kind filters — an offline verifier replays every
    event): ``limit`` defaults to 50 and must be 1-200, ``cursor``
    defaults to 0; both must be plain decimals without leading zeros.
    Items are the events in ascending ``event_id``, each carrying its
    ``prev_hash``/``event_hash`` links. The response additionally
    contains:

    * ``anchor_hash`` — the hash immediately preceding the page's first
      event (64 zeroes at cursor 0; the head at cursor == total);
    * ``checkpoint`` — the current ``{event_id, event_hash}`` log head
      (``{0, "0"*64}`` for an empty log), included on every page;
    * ``checkpoint_auth`` — ``{key_version, signature}`` binding that
      checkpoint (and the genesis anchor) under the current audit signer;
      the same envelope is returned on every page of one export.

    ``cursor == total`` returns an empty last page (its anchor is the log
    head so the final page matches the checkpoint); ``cursor > total`` is
    400.
    """
    limit = self.AUDIT_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.AUDIT_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 200"}
        limit = parsed
    cursor = 0
    if params.get("cursor") is not None:
        parsed = _parse_decimal(params["cursor"])
        if parsed is None:
            return 400, {"error": "cursor must be a non-negative decimal"}
        cursor = parsed

    with self.store.lock:
        # Sweep due expiries first, exactly like /v1/audit/events, so the
        # exported checkpoint and log never lag a durable expiry.
        self._prune_expired_syncs()
        events = self.store.audit_events
        total = len(events)
        if cursor > total:
            return 400, {"error": "cursor is beyond the result set"}
        page = [dict(event) for event in events[cursor : cursor + limit]]
        # The anchor is the predecessor hash of the page's first event;
        # for an empty terminal page it is the current log head, which the
        # offline verifier requires the last page to meet.
        if cursor == 0:
            anchor_hash = audit.ZERO_HASH
        else:
            anchor_hash = events[cursor - 1]["event_hash"]
        next_cursor = cursor + limit if cursor + limit < total else None
        body = {
            "items": page,
            "total": total,
            "next_cursor": next_cursor,
            "anchor_hash": anchor_hash,
            "checkpoint": dict(self.store.audit_checkpoint),
            # One fresh signature over the current head on every request;
            # every page fetched in the same export binds the identical
            # checkpoint and therefore the same verifiable envelope.
            "checkpoint_auth": self.store.sign_checkpoint(),
        }
    return 200, body

